{
  "title": "太空裂缝",
  "scene": "你漂浮在一片漆黑的太空中，周围是冰冷的金属舱壁。突然，飞船的一侧出现了一个巨大的裂缝，里面似乎有某种未知的气体。你的氧气供应已经接近耗尽，必须尽快找到封闭裂缝的方法或找到安全的出口。",
  "goal": "找到封闭裂缝的方法或安全的出口，确保氧气供应不断。",
  "choices": [
    {
      "id": "A",
      "text": "检查裂缝周围是否有可以固定的金属板或工具。",
      "outcome": "你发现了一块可以利用的金属板，但它的大小不够覆盖裂缝。尝试用金属板边缘卡住裂缝边缘，虽然不完全密封，但至少减缓了气体的泄漏，延长了氧气供应时间。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "尝试激活飞船的紧急氧气供应系统，希望能额外获得一些氧气。",
      "outcome": "紧急氧气供应系统无法启动，可能是电源中断了。你听到远处有微弱的警报声，似乎有其他系统也在受到影响。",
      "result": "fail",
      "next": "bad_end"
    },
    {
      "id": "C",
      "text": "探索裂缝附近是否有可以利用的设备或者舱门。",
      "outcome": "你找到了一个可以打开的舱门，但门后是一个充满未知气体的狭窄通道。经过仔细观察，你确认这个通道可以通向另一个舱室，也许那里有你需要的资源。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
